//! Records a corpus of real frame traffic: one JSON text per line, each the `frame` event a pane sends to the page.
//!
//!   cargo run -p holzwave-spike --bin record_frames -- <workload> <out>
//!
//! The workloads are `typing`, `listing`, `cat-large` and `redraw`. Each runs in a pane of 120 by 40 cells, the real
//! `PaneHandle` with the real engine and the real frame encoder, so the frames are the ones the desktop hands to the
//! page, including the pacing of one frame per 8 ms. The files are regenerated by this command and are not committed.
//!
//! The JSON is written by a small emitter in this file, not by serde: this crate has no serde_json dependency and the
//! lock must stay as it is. The emitter follows the derived `Serialize` of `FrameMsg` field by field, and the wire
//! measurement project checks that every recorded line is exactly what serde_json writes for the same value.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::mpsc;
use std::time::Duration;

use holzwave_core::pane::{PaneEvent, PaneHandle, PaneSpec};
use holzwave_core::wire::{FrameMsg, RowMsg};

const COLS: u16 = 120;
const ROWS: u16 = 40;
/// How long a workload may run before the recorder gives up.
const RUN_LIMIT: Duration = Duration::from_secs(300);
/// The size the large text file is cut to (whole files only; the last one is cut at a line end).
const LARGE_BYTES: usize = 2_560 * 1024;

/// JSON string escaping the way serde_json does it: `"` and `\`, the short forms of the control characters that have
/// one, `\u00xx` in lower case for the others, everything else (DEL and non-ASCII too) as it is.
fn string(out: &mut String, text: &str) {
    out.push('"');
    for c in text.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

fn row(out: &mut String, r: &RowMsg) {
    let _ = write!(out, "{{\"y\":{},\"runs\":[", r.y);
    for (i, run) in r.runs.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push('[');
        string(out, &run.0);
        let _ = write!(out, ",{},{},{},{}]", run.1, run.2, run.3, run.4);
    }
    out.push(']');
    if !r.extras.is_empty() {
        out.push_str(",\"extras\":[");
        for (i, (x, tail)) in r.extras.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            let _ = write!(out, "[{x},");
            string(out, tail);
            out.push(']');
        }
        out.push(']');
    }
    out.push('}');
}

/// One frame as the compact JSON text the page receives.
fn frame_json(f: &FrameMsg) -> String {
    let mut out = String::with_capacity(512);
    let _ = write!(
        out,
        "{{\"pane\":{},\"seq\":{},\"full\":{},\"cols\":{},\"rows\":{},\"fg\":{},\"bg\":{},\"cursor\":",
        f.pane, f.seq, f.full, f.cols, f.rows, f.fg, f.bg
    );
    match &f.cursor {
        None => out.push_str("null"),
        Some(c) => {
            let style = match c.style {
                holzwave_core::wire::CursorShape::Block => "block",
                holzwave_core::wire::CursorShape::Bar => "bar",
                holzwave_core::wire::CursorShape::Underline => "underline",
                holzwave_core::wire::CursorShape::Hollow => "hollow",
            };
            let _ = write!(out, "{{\"x\":{},\"y\":{},\"style\":\"{style}\",\"blink\":{}}}", c.x, c.y, c.blink);
        }
    }
    let _ = write!(out, ",\"scrollbar\":[{},{},{}]", f.scrollbar.0, f.scrollbar.1, f.scrollbar.2);
    out.push_str(",\"selection\":[");
    for (i, s) in f.selection.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        let _ = write!(out, "[{},{},{}]", s.0, s.1, s.2);
    }
    out.push_str("],\"matches\":[");
    for (i, m) in f.matches.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        let _ = write!(out, "[{},{},{},{}]", m.0, m.1, m.2, m.3);
    }
    out.push_str("],\"search\":");
    match &f.search {
        None => out.push_str("null"),
        Some(s) => {
            let _ = write!(out, "{{\"total\":{},\"current\":", s.total);
            match s.current {
                None => out.push_str("null"),
                Some(n) => {
                    let _ = write!(out, "{n}");
                }
            }
            out.push('}');
        }
    }
    out.push_str(",\"copy_cursor\":");
    match f.copy_cursor {
        None => out.push_str("null"),
        Some((x, y)) => {
            let _ = write!(out, "[{x},{y}]");
        }
    }
    let _ = write!(
        out,
        ",\"modes\":{{\"alt\":{},\"bracketed_paste\":{},\"mouse\":{}}},\"changed\":[",
        f.modes.alt, f.modes.bracketed_paste, f.modes.mouse
    );
    for (i, r) in f.changed.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        row(&mut out, r);
    }
    out.push_str("]}");
    out
}

enum Msg {
    Frame(String),
    Exited,
    Failed(String),
}

/// The repository root: the parent of this crate's directory.
fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).parent().expect("the crate sits in the repository").to_path_buf()
}

/// A command line of 400 characters, typed one key at a time. It is never run: no Enter is sent.
fn typed_line() -> String {
    const WORDS: &[&str] = &[
        "git", "log", "--oneline", "--decorate", "--graph", "--all", "|", "grep", "-i", "frame", "|", "sort", "|", "uniq",
        "-c", "|", "head", "-n", "20", ">", "/tmp/notes.txt", "&&", "cat", "/tmp/notes.txt", "|", "wc", "-l",
    ];
    let mut line = String::new();
    let mut i = 0;
    while line.len() < 400 {
        let word = WORDS[i % WORDS.len()];
        if line.len() + word.len() + 1 > 400 {
            // Fill the last characters so that the line is exactly 400 characters long.
            while line.len() < 400 {
                line.push('x');
            }
            break;
        }
        if !line.is_empty() {
            line.push(' ');
        }
        line.push_str(word);
        i += 1;
    }
    line
}

/// The text of the repository's tracked Markdown files, whole files concatenated, cut at a line end near `LARGE_BYTES`.
fn large_text(root: &Path) -> Result<String, String> {
    let listing = Command::new("git")
        .arg("-C")
        .arg(root)
        .args(["ls-files", "-z", "*.md"])
        .output()
        .map_err(|e| format!("git ls-files: {e}"))?;
    if !listing.status.success() {
        return Err("git ls-files failed".into());
    }
    let mut text = String::new();
    for name in listing.stdout.split(|b| *b == 0).filter(|n| !n.is_empty()) {
        let name = String::from_utf8_lossy(name).into_owned();
        let Ok(part) = std::fs::read_to_string(root.join(&name)) else { continue };
        text.push_str(&part);
        if !text.ends_with('\n') {
            text.push('\n');
        }
        if text.len() >= LARGE_BYTES {
            break;
        }
    }
    if text.len() < 2 * 1024 * 1024 {
        return Err(format!("the Markdown files hold only {} bytes, 2 MiB are needed", text.len()));
    }
    Ok(text)
}

fn run(workload: &str, out: &Path) -> Result<(), String> {
    let root = repo_root();
    let mut large_input: Option<PathBuf> = None;
    let spec = PaneSpec::new("sh", COLS, ROWS).cwd(&root);
    let spec = match workload {
        "typing" => spec,
        "listing" => spec.args(["-c", "ls -lR core"]),
        "cat-large" => {
            // The text file lives in the system temp folder, not in the repository: the policy scan reads every text
            // file under the repository, and this one is a copy of other files.
            let input = std::env::temp_dir().join(format!("holzwave-cat-large-{}.txt", std::process::id()));
            std::fs::write(&input, large_text(&root)?).map_err(|e| format!("{}: {e}", input.display()))?;
            large_input = Some(input.clone());
            spec.args(["-c".to_string(), format!("cat '{}'", input.display())])
        }
        "redraw" => spec.args([
            "-c",
            "i=0; while [ $i -lt 20 ]; do printf '\\033[H\\033[2J'; n=0; \
             while [ $n -lt 40 ]; do printf 'row %02d  value %6d  checksum %6d\\n' $n $(( (i*7919 + n*104729) % 1000000 )) \
             $(( (i*31 + n*17) % 100000 )); n=$((n+1)); done; sleep 0.05; i=$((i+1)); done",
        ]),
        other => return Err(format!("unknown workload `{other}`; use typing, listing, cat-large or redraw")),
    };

    let (tx, rx) = mpsc::channel::<Msg>();
    let pane = PaneHandle::spawn_ghostty(1, spec, move |event| {
        let _ = match event {
            PaneEvent::Frame(f) => tx.send(Msg::Frame(frame_json(&f))),
            PaneEvent::Exited { .. } => tx.send(Msg::Exited),
            PaneEvent::Failed(why) => tx.send(Msg::Failed(why)),
            _ => Ok(()),
        };
    })
    .map_err(|e| format!("the pane did not start: {e}"))?;

    let mut lines: Vec<String> = Vec::new();
    if workload == "typing" {
        // The shell prompt first, then one key every 20 ms: a frame per key.
        drain(&rx, &mut lines, Duration::from_millis(600))?;
        for c in typed_line().chars() {
            pane.text(c.to_string()).map_err(|e| format!("typing: {e}"))?;
            drain(&rx, &mut lines, Duration::from_millis(20))?;
        }
        drain(&rx, &mut lines, Duration::from_millis(300))?;
        pane.close();
    }
    let deadline = std::time::Instant::now() + RUN_LIMIT;
    loop {
        let left = deadline.saturating_duration_since(std::time::Instant::now());
        match rx.recv_timeout(left) {
            Ok(Msg::Frame(line)) => lines.push(line),
            Ok(Msg::Exited) => break,
            Ok(Msg::Failed(why)) => return Err(format!("the pane failed: {why}")),
            Err(_) => return Err("the workload did not end in time".into()),
        }
    }
    if let Some(input) = large_input {
        let _ = std::fs::remove_file(input);
    }
    if lines.is_empty() {
        return Err("no frame was recorded".into());
    }
    if let Some(dir) = out.parent() {
        std::fs::create_dir_all(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
    }
    let mut text = String::new();
    for line in &lines {
        text.push_str(line);
        text.push('\n');
    }
    std::fs::write(out, &text).map_err(|e| format!("{}: {e}", out.display()))?;
    eprintln!("{workload}: {} frames, {} bytes, {}", lines.len(), text.len(), out.display());
    Ok(())
}

/// Collect what arrives within `wait`; an exit or a failure that arrives early is an error for the typing workload.
fn drain(rx: &mpsc::Receiver<Msg>, lines: &mut Vec<String>, wait: Duration) -> Result<(), String> {
    let end = std::time::Instant::now() + wait;
    loop {
        let left = end.saturating_duration_since(std::time::Instant::now());
        match rx.recv_timeout(left) {
            Ok(Msg::Frame(line)) => lines.push(line),
            Ok(Msg::Exited) => return Err("the shell ended while typing".into()),
            Ok(Msg::Failed(why)) => return Err(format!("the pane failed: {why}")),
            Err(_) => return Ok(()),
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let [workload, out] = args.as_slice() else {
        eprintln!("usage: record_frames <typing|listing|cat-large|redraw> <out.ndjson>");
        std::process::exit(2);
    };
    if let Err(why) = run(workload, Path::new(out)) {
        eprintln!("record_frames: {why}");
        std::process::exit(1);
    }
}
